import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long amount = Long.parseLong(next());
        long[] coins = new long[(int) n];
        for (int i = 0; i < coins.length; i++) coins[i] = Long.parseLong(next());

        int target = (int) amount;
        long inf = target + 1;
        long[] best = new long[target + 1];
        Arrays.fill(best, inf);
        best[0] = 0;
        for (int k = 0; k < n; k++) {
            int c = (int) coins[k];
            for (int v = c; v <= target; v++) {
                if (best[v - c] + 1 < best[v]) best[v] = best[v - c] + 1;
            }
        }
        System.out.println(best[target] < inf ? best[target] : -1);
    }
}
